        raise ValueError(
            "ledger proof manifest does not re-digest to the snapshot"
        )
    if sum(meta["entries"] for meta in metas) != snapshot["entries"]:
        raise ValueError(
            "ledger proof snapshot entry count does not match the "
            "manifest"
